# Hypothesis for particle system
# PLEKT moves toward nearest WOVVE (by wovve_dist) with step sign(wrap_dx, wrap_dy)
# WOVVE moves based on nearest PLEKT - trying fleeing behavior
# New WOVVE spawns at anti-pole under certain conditions

def sign(val):
    if val == 0:
        return 0
    elif val > 0:
        return 1
    else:
        return -1

def wrap(val):
    """Wrap value to range [-4, 3] on 8-torus"""
    v = val % 8
    if v > 4:
        v -= 8
    return v

def wovve_dist(p, q):
    """|wrap_dx|^2 + |wrap_dy|"""
    dx = wrap(p['x'] - q['x'])
    dy = wrap(p['y'] - q['y'])
    return dx*dx + abs(dy)

def chebyshev_dist(p, q):
    """max(|wrap_dx|, |wrap_dy|)"""
    dx = abs(wrap(p['x'] - q['x']))
    dy = abs(wrap(p['y'] - q['y']))
    return max(dx, dy)

def hidden_rule_fn(state):
    # Separate PLEKTs and WOVVEs
    plekts = [p for p in state if p['type'] == 'PLEKT']
    wovves = [p for p in state if p['type'] == 'WOVVE']

    # If no WOVVEs, state doesn't change
    if not wovves:
        return state[:]

    # For each PLEKT, find nearest WOVVE by wovve_dist
    # PLEKT moves by sign(wrap_dx, wrap_dy) toward nearest WOVVE
    # sign(0)=0, sign(n>0)=1, sign(n<0)=-1, sign(±4)=1
    def sign_with_tie(val):
        if val == 0:
            return 0
        elif val > 0:
            return 1
        elif val < 0:
            return -1
        else:
            return 1  # sign(4) = 1, sign(-4) = 1

    new_plekts = []
    for p in plekts:
        # Find nearest WOVVE by wovve_dist
        best_wovve = None
        best_dist = float('inf')
        for w in wovves:
            d = wovve_dist(p, w)
            if d < best_dist:
                best_dist = d
                best_wovve = w

        if best_wovve:
            dx = wrap(best_wovve['x'] - p['x'])
            dy = wrap(best_wovve['y'] - p['y'])
            new_x = (p['x'] + sign_with_tie(dx)) % 8
            new_y = (p['y'] + sign_with_tie(dy)) % 8
            new_plekts.append({'type': 'PLEKT', 'x': new_x, 'y': new_y})

    # For each WOVVE, find nearest PLEKT by Chebyshev distance
    # WOVVE tries to flee - moves opposite to nearest PLEKT
    # Using sign with sign(±4) = 0
    def sign_wovve(val):
        if val == 0:
            return 0
        elif val > 0:
            return 1
        else:
            return -1

    new_wovves = []
    for w in wovves:
        # Find nearest PLEKT by Chebyshev distance
        best_plekt = None
        best_dist = float('inf')
        for p in plekts:
            d = chebyshev_dist(w, p)
            if d < best_dist:
                best_dist = d
                best_plekt = p

        if best_plekt:
            dx = wrap(best_plekt['x'] - w['x'])
            dy = wrap(best_plekt['y'] - w['y'])
            # Flee: move in opposite direction
            new_x = (w['x'] - sign_wovve(dx)) % 8
            new_y = (w['y'] - sign_wovve(dy)) % 8
            new_wovves.append({'type': 'WOVVE', 'x': new_x, 'y': new_y})

    # Spawn new WOVVE at anti-pole of WOVVE with largest wovve_dist to nearest PLEKT
    # Only spawn if certain condition met (trying: if any WOVVE increased its distance)
    # For now, always spawn at anti-pole of WOVVE with max wovve_dist
    new_wovvves = list(new_wovves)  # copy

    # Find WOVVE with largest wovve_dist to nearest PLEKT
    max_dist = -1
    target_wovvve = None
    for w in wovves:
        best_dist = float('inf')
        for p in plekts:
            d = chebyshev_dist(w, p)
            if d < best_dist:
                best_dist = d
        # wovve_dist to nearest PLEKT
        wd = float('inf')
        for p in plekts:
            d = wovve_dist(w, p)
            if d < wd:
                wd = d
        if wd > max_dist:
            max_dist = wd
            target_wovvve = w

    if target_wovvve:
        anti_x = (target_wovvve['x'] + 4) % 8
        anti_y = (target_wovvve['y'] + 4) % 8
        # Check if anti-pole is not occupied by a PLEKT in the new state
        occupied = any(p['x'] == anti_x and p['y'] == anti_y for p in new_plekts)
        if not occupied:
            new_wovvves.append({'type': 'WOVVE', 'x': anti_x, 'y': anti_y})

    return new_plekts + new_wovvves
